const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // The question asks for November 8, 2024, which is in the future.
    // GEE cannot provide future data. Assuming the user meant November 8, 2023.
    const targetDate = '2023-11-08';
    const endDate = '2023-11-09'; // For a single day

    // Load administrative boundaries for Indian states
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level2');
    const punjab = gaul.filter(ee.Filter.eq('ADM1_NAME', 'Punjab'));
    const haryana = gaul.filter(ee.Filter.eq('ADM1_NAME', 'Haryana'));

    if (punjab.size().getInfo() === 0 || haryana.size().getInfo() === 0) {
      console.log("Could not find administrative boundaries for Punjab or Haryana.");
      console.log("D"); // Data/Region name error
      return;
    }

    const punjabGeom = punjab.geometry();
    const haryanaGeom = haryana.geometry();

    // 2. Data Acquisition & Check
    // MODIS Thermal Anomalies / Fire Daily (MOD14A1)
    const fireCollection = ee.ImageCollection('MODIS/061/MOD14A1')
      .filterDate(targetDate, endDate)
      .select('FireMask');

    const collectionSize = fireCollection.size().getInfo();

    if (collectionSize === 0) {
      console.log(`No MODIS fire data found for ${targetDate}.`);
      console.log("C1"); // Empty Collection
      return;
    }
    console.log(`MODIS Images for ${targetDate}: ${collectionSize}`);

    const fireImage = fireCollection.first();

    // 3. Processing: Calculate active fire pixel count for each state
    const calculateFirePixels = (image, geometry, regionName) => {
      // Create a binary image where fire pixels (FireMask > 0) are 1, others 0.
      // FireMask values: 0=no fire, 1-6=non-fire, 7=low confidence fire, 8=nominal confidence fire, 9=high confidence fire.
      // We count any detected fire (value > 0).
      const firePixels = image.gt(0).rename('fire_count');

      // Reduce region to get the sum of fire pixels
      const fireCount = firePixels.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 1000, // MODIS resolution is 1km
        maxPixels: 1e9,
        crs: 'EPSG:4326' // Specify CRS for consistency
      }).get('fire_count').getInfo();

      return fireCount;
    };

    const punjabFireCount = calculateFirePixels(fireImage, punjabGeom, 'Punjab');
    const haryanaFireCount = calculateFirePixels(fireImage, haryanaGeom, 'Haryana');

    // 4. Validation & Final Answer
    if (punjabFireCount === null || haryanaFireCount === null) {
      console.log("Calculation failed: Fire count is None for one or both states.");
      console.log("C3"); // Calculation Failure
      return;
    }

    console.log(`Punjab Fire Counts (${targetDate}): ${punjabFireCount}`);
    console.log(`Haryana Fire Counts (${targetDate}): ${haryanaFireCount}`);

    if (punjabFireCount === 0 && haryanaFireCount === 0) {
      console.log("No valid fire pixels found in either state after processing.");
      console.log("C2"); // No Valid Pixels
      return;
    }

    if (punjabFireCount > haryanaFireCount) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No (includes equal counts or less)
    }

  } catch (error) {
    console.log(`An error occurred: ${error.message}`);
    console.log("D"); // General error/syntax/method error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
